import {statIcon} from './stat-view.js';
import {ACHIEVEMENT_TRACKS,REWARD_QUESTS,TIERS,rewardStatus,normalizeCareer,customAccess} from './career-economy.js';
import {characterProgress,characterStatus,SPECIAL_CHARACTERS} from './founder-options.js';
const number=n=>Math.round(n).toLocaleString('ko-KR');
export const QUESTS=REWARD_QUESTS;
export const questProgress=characterProgress;
const rewardLabel=q=>q.character?`${SPECIAL_CHARACTERS.find(p=>p.id===q.character).name} 해금`:'커스텀 1회권';
export function syncAchievements(state){const progress=questProgress(state),earned={...state.achievements};let changed=false;for(const q of QUESTS)if(!earned[q.id]&&progress[q.metric]>=q.target){earned[q.id]={month:Math.max(1,Math.min(60,state.month-1))};changed=true;}return changed?{...state,achievements:earned}:state;}
export function questStatus(state){const progress=questProgress(state),s=syncAchievements(state);return QUESTS.map(q=>({...q,earned:!!s.achievements?.[q.id],earnedMonth:s.achievements?.[q.id]?.month,value:progress[q.metric]||0,percent:Math.min(100,(progress[q.metric]||0)/q.target*100)}));}
export function questShowcase(state,career={}){
 const meta=normalizeCareer(career),quests=rewardStatus(meta),earned=quests.filter(q=>q.earned),available=earned.filter(q=>!q.claimed).length,next=quests.find(q=>!q.earned);
 return `<section class="quest-showcase" aria-label="성장 업적"><div class="quest-showcase-heading"><h2>성장 업적 <small>${earned.length} / ${quests.length}</small></h2><button class="quiet coin-balance" data-action="coin-store">이용권 ${meta.tickets}장</button></div><div class="quest-showcase-content"><div class="quest-pins"><button class="quiet" data-action="quests">${available?`보상 ${available}개 받기`:'업적 수첩'}</button></div><div class="next-quest"><strong>${next?next.title:'모든 업적 달성!'}</strong>${next?`<div class="quest-progress"><i style="width:${Math.min(100,next.value/next.target*100)}%"></i></div><small>${number(next.value)} / ${number(next.target)}${next.unit} · ${rewardLabel(next)}</small>`:'<small>새 캐릭터의 도전을 시작해 보세요.</small>'}</div></div></section>`;
}
export function questCollection(state,career={}){
 const meta=normalizeCareer(career),quests=rewardStatus(meta),claimable=quests.filter(q=>q.earned&&!q.claimed).length,access=customAccess(meta);
 return `<div class="career-wallet"><div><span>커스텀 모드 1회권</span><strong>${meta.tickets}장</strong><small>${access.free?'오늘 무료 1회 사용 가능':'오늘 무료 이용 완료'}</small></div><button class="primary" data-action="claim-rewards" ${claimable?'':'disabled'}>${claimable?`보상 ${claimable}개 받기`:'받을 보상 없음'}</button></div><p class="career-note">업적 보상은 캐릭터 해금 또는 커스텀 모드 1회권이에요. 각 보상은 한 번만 받아요. 커스텀 플레이는 업적에 반영되지 않아요.</p><div class="tier-collection">${ACHIEVEMENT_TRACKS.map(track=>{const rows=quests.filter(q=>q.track===track.id),next=rows.find(q=>!q.earned)||rows.at(-1);return `<article><div class="tier-heading">${statIcon(track.icon)}<h3>${track.title}</h3><span>${rows.filter(q=>q.earned).length} / 4</span></div><div class="tier-steps">${rows.map(q=>`<div class="tier-step ${q.earned?'achieved':''} ${q.claimed?'claimed':''}"><b>${TIERS[q.tier]}</b><span>${number(q.target)}${q.unit}</span><small>${rewardLabel(q)}</small><small>${q.claimed?'수령 완료':q.earned?'수령 가능':'도전 중'}</small></div>`).join('')}</div><div class="quest-progress"><i style="width:${Math.min(100,next.value/next.target*100)}%"></i></div><small>최고 기록 ${number(next.value)}${next.unit}</small></article>`;}).join('')}${quests.filter(q=>['hard','finale'].includes(q.track)).map(q=>`<article class="finale-achievement">${q.track==='hard'?'<small>고난도 도전</small>':''}<h3>${q.title}</h3><p>${q.description}</p><b>${rewardLabel(q)}</b><small>${q.claimed?'수령 완료':q.earned?'수령 가능':'도전 중'}</small></article>`).join('')}</div><button class="quiet career-store-open" data-action="coin-store">캐릭터와 커스텀 이용권</button>`;
}
export function characterShop(career){
 const meta=normalizeCareer(career),access=customAccess(meta);
 return `<div class="career-wallet"><div><span>커스텀 모드 1회권</span><strong>${meta.tickets}장</strong></div><button class="quiet" data-action="quests">업적 보상</button></div><div class="custom-pass-guide"><b>${access.free?'오늘의 커스텀 무료 1회가 있어요':'오늘 무료 1회를 사용했어요'}</b><p>하루 1회 무료 · 한국 시간 자정에 다시 열려요. 이후에는 새 도전을 시작할 때 이용권 1장을 사용해요. 저장한 게임을 이어할 때는 차감하지 않아요.</p></div>${meta.resetNotice?'<p class="unlock-reset-note">새 해금 기준 적용 · 이전 캐릭터도 새 배지를 달성해 다시 해금해야 해요.</p>':''}<div class="character-shop-list">${characterStatus(meta).map(p=>`<article><span class="portrait-clip sprite-thumb"><img src="assets/${p.file}" alt=""></span><div><h3>${p.name}<small>${p.label}</small></h3><b>${p.industryLabel}</b><p>${p.requirement}</p><small>${p.qualified?'배지 조건 달성':`${number(p.value)} / ${number(p.target)}${p.unit}`}</small></div><button class="${p.unlocked?'quiet':'primary'}" data-action="unlock-character" data-id="${p.id}" ${p.unlocked||!p.qualified?'disabled':''}>${p.unlocked?'해금 완료':'배지로 해금'}</button></article>`).join('')}</div>`;
}
